a.deleted_at = 0 AND NOT EXISTS ( SELECT 1 FROM ad_account_asset newer WHERE newer.account_id = a.account_id AND newer.deleted_at = 0 AND newer.id > a.id ) AND a.channel_id = #{query.channelId}
AND a.account_type = #{query.accountType}
AND a.account_id IN
#{accountId}
AND a.managed_bm_id LIKE CONCAT('%', #{query.bmId}, '%')
AND a.account_attribute LIKE CONCAT('%', #{query.subjectName}, '%')
AND a.timezone = #{query.timezone}
AND EXISTS ( SELECT 1 FROM ad_account_asset_assignment assignment JOIN sys_user operator ON operator.id = assignment.user_id AND operator.deleted_at = 0 WHERE assignment.ad_account_asset_id = a.id AND assignment.assignment_status = 'ACTIVE' AND assignment.deleted_at = 0 AND operator.primary_department_id = #{query.belongTeamId} )
AND a.account_status = #{query.status}
AND () = #{query.usageStatus}
AND EXISTS ( SELECT 1 FROM ad_account_asset_assignment assignment WHERE assignment.ad_account_asset_id = a.id AND assignment.assignment_status = 'ACTIVE' AND assignment.deleted_at = 0 AND assignment.user_name LIKE CONCAT('%', #{query.operatorName}, '%') )
AND (a.account_id LIKE CONCAT('%', #{query.keyword}, '%') OR a.account_name LIKE CONCAT('%', #{query.keyword}, '%') OR a.managed_bm_id LIKE CONCAT('%', #{query.keyword}, '%') OR a.managed_bm LIKE CONCAT('%', #{query.keyword}, '%'))

c.deleted_at = 0

    AND (c.channel_name LIKE CONCAT('%', #{query.channelName}, '%')
        OR c.channel_short_name LIKE CONCAT('%', #{query.channelName}, '%')
        OR c.channel_code LIKE CONCAT('%', #{query.channelName}, '%'))

AND c.status = #{query.status}

    AND c.belong_team = #{query.belongTeam}

mapper.select:
SELECT 
FROM media_channel c WHERE 
ORDER BY c.updated_at DESC, c.id DESC LIMIT #{offset}, #{pageSize}

SELECT MIN(a.id) AS id, a.account_type, a.account_attribute AS subject_name, c.channel_name, c.channel_type, COALESCE(SUM((SELECT SUM(s.spend_amount) FROM media_channel_campaign_spend s WHERE s.account_id = a.account_id AND s.deleted_at = 0)), 0) AS total_consumption, CASE WHEN SUM(CASE WHEN EXISTS ( SELECT 1 FROM ad_account_asset_assignment assignment WHERE assignment.ad_account_asset_id = a.id AND assignment.assignment_status = 'ACTIVE' AND assignment.deleted_at = 0 ) THEN 1 ELSE 0 END) > 0 THEN '使用中' ELSE '未使用' END AS usage_status FROM ad_account_asset a JOIN media_channel c ON c.id = a.channel_id AND c.deleted_at = 0 WHERE a.deleted_at = 0 AND NOT EXISTS ( SELECT 1 FROM ad_account_asset newer WHERE newer.account_id = a.account_id AND newer.deleted_at = 0 AND newer.id > a.id )
AND c.channel_name LIKE CONCAT('%', #{query.channelName}, '%')
AND c.status = #{query.status} GROUP BY a.account_type, a.account_attribute, c.id, c.channel_name, c.channel_type ORDER BY total_consumption DESC, c.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM media_channel_rate
WHERE channel_id = #{channelId} AND deleted_at = 0
AND id != #{excludedId}
AND effective_date <= COALESCE(#{expiryDate}, '9999-12-31')
AND COALESCE(expiry_date, '9999-12-31') >= #{effectiveDate}

