mapper.update:
UPDATE media_channel_rate SET service_fee = #{serviceFee}, rebate_rate = #{rebateRate},
    effective_date = #{effectiveDate}, expiry_date = #{expiryDate}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted_at = 0

