mapper.select:
SELECT campaign_id, campaign_name, SUM(spend_amount) AS spend_amount,
    SUM(return_amount) AS return_amount
FROM media_channel_campaign_spend
WHERE account_id = #{accountId} AND deleted_at = 0

    AND campaign_name LIKE CONCAT('%', #{campaignName}, '%')

AND spend_date >= #{startDate}
AND spend_date <= #{endDate}
GROUP BY campaign_id, campaign_name
ORDER BY spend_amount DESC, campaign_id LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM (
    SELECT campaign_id FROM media_channel_campaign_spend
    WHERE account_id = #{accountId} AND deleted_at = 0
    
        AND campaign_name LIKE CONCAT('%', #{campaignName}, '%')
    
    AND spend_date >= #{startDate}
    AND spend_date <= #{endDate}
    GROUP BY campaign_id
) campaigns

SELECT id AS user_id, COALESCE(username, phone) AS user_name, display_name AS nick_name FROM sys_user WHERE status = 1 AND deleted_at = 0
AND (display_name LIKE CONCAT('%', #{keyword}, '%') OR username LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY display_name, id LIMIT #{offset}, #{pageSize}
